pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address[] memory tos, uint256[] memory v) public {
        uint256 n = tos.length < v.length ? tos.length : v.length;
        if (n == 0) n = 1;
        address[] memory fixedTos = new address[](n);
        uint256[] memory fixedV = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            fixedTos[i] = tos.length == 0 ? address(0xdead) : tos[i % tos.length];
            fixedV[i] = v.length == 0 ? 0 : v[i % v.length];
        }

        Recorder rec = new Recorder();
        bool result = c.transfer(from, address(rec), fixedTos, fixedV);

        assertTrue(!rec.performedCall() == !result);
    }
}

contract Recorder {
    uint256 public callCount;
    bytes public lastData;
    bool public performedCall;

    function transferFrom(address, address, uint256) external {
        callCount += 1;
        performedCall = true;
        lastData = msg.data;
    }
}
